import React, { useEffect, useRef, useState } from 'react';
import { toast } from 'react-toastify';
import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiBookOpen,
  FiGrid,
  FiCheckCircle,
  FiXCircle,
  FiStar,
  FiImage,
  FiClock,
  FiTag,
} from 'react-icons/fi';

import api, { getApiErrorMessage } from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

// =====================================================
// INITIAL COURSE FORM
// =====================================================
const initialCourseForm = {
  title: '',
  slug: '',
  description: '',
  short_description: '',
  duration: '',
  level: '',
  price: '',
  is_active: true,
  is_featured: false,
  order: 0,
  category_id: '',
};

// =====================================================
// INITIAL CATEGORY FORM
// =====================================================
const initialCategoryForm = {
  name: '',
  slug: '',
  description: '',
  is_active: true,
  order: 0,
};

const AdminCourses = () => {
  // ===================================================
  // GENERAL STATE
  // ===================================================
  const [courses, setCourses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);

  // ===================================================
  // COURSE STATE
  // ===================================================
  const [courseModalOpen, setCourseModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState(null);
  const [courseFormData, setCourseFormData] =
    useState(initialCourseForm);

  const [courseImageFile, setCourseImageFile] = useState(null);
  const [courseImagePreview, setCourseImagePreview] = useState('');
  const [courseSubmitting, setCourseSubmitting] = useState(false);

  const courseFileRef = useRef(null);

  // ===================================================
  // CATEGORY STATE
  // ===================================================
  const [categoryModalOpen, setCategoryModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState(null);
  const [categoryFormData, setCategoryFormData] =
    useState(initialCategoryForm);

  const [categoryImageFile, setCategoryImageFile] = useState(null);
  const [categoryImagePreview, setCategoryImagePreview] = useState('');
  const [categorySubmitting, setCategorySubmitting] = useState(false);

  const categoryFileRef = useRef(null);

  // ===================================================
  // LOAD DATA
  // ===================================================
  useEffect(() => {
    fetchData();
  }, []);

  // ===================================================
  // FETCH COURSES + CATEGORIES
  // ===================================================
  const fetchData = async () => {
    try {
      setLoading(true);

      const [coursesResponse, categoriesResponse] = await Promise.all([
        api.get('/api/courses/?is_active=true'),
        api.get('/api/courses/categories'),
      ]);

      setCourses(
        Array.isArray(coursesResponse.data)
          ? coursesResponse.data
          : []
      );

      setCategories(
        Array.isArray(categoriesResponse.data)
          ? categoriesResponse.data
          : []
      );
    } catch (error) {
      console.error('Fetch courses error:', error);

      toast.error(
        getApiErrorMessage(
          error,
          'Failed to load courses data'
        )
      );
    } finally {
      setLoading(false);
    }
  };

  // ===================================================
  // CREATE SLUG
  // ===================================================
  const createSlug = (value) => {
    return value
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');
  };

  // ===================================================
  // RESET COURSE
  // ===================================================
  const resetCourseForm = () => {
    setEditingCourse(null);
    setCourseFormData(initialCourseForm);
    setCourseImageFile(null);
    setCourseImagePreview('');

    if (courseFileRef.current) {
      courseFileRef.current.value = '';
    }
  };

  // ===================================================
  // RESET CATEGORY
  // ===================================================
  const resetCategoryForm = () => {
    setEditingCategory(null);
    setCategoryFormData(initialCategoryForm);
    setCategoryImageFile(null);
    setCategoryImagePreview('');

    if (categoryFileRef.current) {
      categoryFileRef.current.value = '';
    }
  };

  // ===================================================
  // OPEN ADD COURSE
  // ===================================================
  const handleAddCourse = () => {
    resetCourseForm();
    setCourseModalOpen(true);
  };

  // ===================================================
  // OPEN ADD CATEGORY
  // ===================================================
  const handleAddCategory = () => {
    resetCategoryForm();
    setCategoryModalOpen(true);
  };

  // ===================================================
  // CLOSE COURSE MODAL
  // ===================================================
  const closeCourseModal = () => {
    setCourseModalOpen(false);
    resetCourseForm();
  };

  // ===================================================
  // CLOSE CATEGORY MODAL
  // ===================================================
  const closeCategoryModal = () => {
    setCategoryModalOpen(false);
    resetCategoryForm();
  };

  // ===================================================
  // COURSE IMAGE CHANGE
  // ===================================================
  const handleCourseImageChange = (e) => {
    const file = e.target.files?.[0];

    if (!file) {
      setCourseImageFile(null);
      setCourseImagePreview('');
      return;
    }

    setCourseImageFile(file);
    setCourseImagePreview(URL.createObjectURL(file));
  };

  // ===================================================
  // CATEGORY IMAGE CHANGE
  // ===================================================
  const handleCategoryImageChange = (e) => {
    const file = e.target.files?.[0];

    if (!file) {
      setCategoryImageFile(null);
      setCategoryImagePreview('');
      return;
    }

    setCategoryImageFile(file);
    setCategoryImagePreview(URL.createObjectURL(file));
  };

  // ===================================================
  // COURSE SUBMIT
  // ===================================================
  const handleCourseSubmit = async (e) => {
    e.preventDefault();

    try {
      setCourseSubmitting(true);

      const fd = new FormData();

      fd.append('title', courseFormData.title);
      fd.append('slug', courseFormData.slug);
      fd.append(
        'description',
        courseFormData.description || ''
      );
      fd.append(
        'short_description',
        courseFormData.short_description || ''
      );
      fd.append(
        'duration',
        courseFormData.duration || ''
      );
      fd.append(
        'level',
        courseFormData.level || ''
      );
      fd.append(
        'price',
        courseFormData.price || ''
      );
      fd.append(
        'is_active',
        String(courseFormData.is_active)
      );
      fd.append(
        'is_featured',
        String(courseFormData.is_featured)
      );
      fd.append(
        'order',
        String(courseFormData.order || 0)
      );
      fd.append(
        'category_id',
        String(courseFormData.category_id)
      );

      if (courseImageFile) {
        fd.append(
          'image_file',
          courseImageFile
        );
      }

      if (editingCourse) {
        await api.put(
          `/api/courses/${editingCourse.id}`,
          fd,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
            },
          }
        );

        toast.success(
          'Course updated successfully'
        );
      } else {
        await api.post(
          '/api/courses/',
          fd,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
            },
          }
        );

        toast.success(
          'Course created successfully'
        );
      }

      closeCourseModal();

      await fetchData();
    } catch (error) {
      console.error('Save course error:', error);

      toast.error(
        error.response?.data?.detail ||
          'Failed to save course'
      );
    } finally {
      setCourseSubmitting(false);
    }
  };

  // ===================================================
  // EDIT COURSE
  // ===================================================
  const handleEditCourse = (course) => {
    setEditingCourse(course);

    setCourseFormData({
      title: course.title || '',
      slug: course.slug || '',
      description: course.description || '',
      short_description:
        course.short_description || '',
      duration: course.duration || '',
      level: course.level || '',
      price: course.price || '',
      is_active: !!course.is_active,
      is_featured: !!course.is_featured,
      order: course.order || 0,
      category_id: course.category_id || '',
    });

    setCourseImageFile(null);
    setCourseImagePreview(
      course.image_url || ''
    );

    setCourseModalOpen(true);
  };

  // ===================================================
  // DELETE COURSE
  // ===================================================
  const handleDeleteCourse = async (id) => {
    const confirmed = window.confirm(
      'Are you sure you want to delete this course?'
    );

    if (!confirmed) return;

    try {
      await api.delete(
        `/api/courses/${id}`
      );

      toast.success(
        'Course deleted successfully'
      );

      await fetchData();
    } catch (error) {
      console.error('Delete course error:', error);

      toast.error(
        getApiErrorMessage(
          error,
          'Failed to delete course'
        )
      );
    }
  };

  // ===================================================
  // CATEGORY SUBMIT
  // ===================================================
  const handleCategorySubmit = async (e) => {
    e.preventDefault();

    try {
      setCategorySubmitting(true);

      const fd = new FormData();

      fd.append(
        'name',
        categoryFormData.name
      );

      fd.append(
        'slug',
        categoryFormData.slug
      );

      fd.append(
        'description',
        categoryFormData.description || ''
      );

      fd.append(
        'is_active',
        String(categoryFormData.is_active)
      );

      fd.append(
        'order',
        String(categoryFormData.order || 0)
      );

      if (categoryImageFile) {
        fd.append(
          'image_file',
          categoryImageFile
        );
      }

      if (editingCategory) {
        await api.put(
          `/api/courses/categories/${editingCategory.id}`,
          fd,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
            },
          }
        );

        toast.success(
          'Category updated successfully'
        );
      } else {
        await api.post(
          '/api/courses/categories',
          fd,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
            },
          }
        );

        toast.success(
          'Category created successfully'
        );
      }

      closeCategoryModal();

      await fetchData();
    } catch (error) {
      console.error(
        'Save category error:',
        error
      );

      toast.error(
        error.response?.data?.detail ||
          'Failed to save category'
      );
    } finally {
      setCategorySubmitting(false);
    }
  };

  // ===================================================
  // EDIT CATEGORY
  // ===================================================
  const handleEditCategory = (category) => {
    setEditingCategory(category);

    setCategoryFormData({
      name: category.name || '',
      slug: category.slug || '',
      description:
        category.description || '',
      is_active: !!category.is_active,
      order: category.order || 0,
    });

    setCategoryImageFile(null);

    setCategoryImagePreview(
      category.image_url || ''
    );

    setCategoryModalOpen(true);
  };

  // ===================================================
  // DELETE CATEGORY
  // ===================================================
  const handleDeleteCategory = async (id) => {
    const confirmed = window.confirm(
      'Are you sure you want to delete this category?'
    );

    if (!confirmed) return;

    try {
      await api.delete(
        `/api/courses/categories/${id}`
      );

      toast.success(
        'Category deleted successfully'
      );

      await fetchData();
    } catch (error) {
      console.error(
        'Delete category error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          'Failed to delete category'
        )
      );
    }
  };

  // ===================================================
  // STATISTICS
  // ===================================================
  const activeCourses = courses.filter(
    (course) => course.is_active
  ).length;

  const featuredCourses = courses.filter(
    (course) => course.is_featured
  ).length;

  const activeCategories = categories.filter(
    (category) => category.is_active
  ).length;

  // ===================================================
  // COURSE COLUMNS
  // ===================================================
  const courseColumns = [
    {
      key: 'image_url',
      label: 'Image',

      render: (val) => (
        <div
          className="
            w-16
            h-12
            rounded-lg
            overflow-hidden
            bg-gray-100
            border
            border-gray-100
          "
        >
          {val ? (
            <img
              src={val}
              alt="Course"
              className="
                w-full
                h-full
                object-cover
              "
            />
          ) : (
            <div
              className="
                w-full
                h-full
                flex
                items-center
                justify-center
                text-gray-400
              "
            >
              <FiImage />
            </div>
          )}
        </div>
      ),
    },

    {
      key: 'title',
      label: 'Course',

      render: (val, row) => (
        <div className="max-w-[220px]">
          <p
            className="
              text-sm
              font-bold
              text-blue-900
              truncate
            "
          >
            {val || 'Untitled'}
          </p>

          {row.short_description && (
            <p
              className="
                text-xs
                text-gray-400
                mt-1
                truncate
              "
            >
              {row.short_description}
            </p>
          )}
        </div>
      ),
    },

    {
      key: 'category_id',
      label: 'Category',

      render: (val) => {
        const category =
          categories.find(
            (item) =>
              String(item.id) === String(val)
          );

        return (
          <span
            className="
              inline-flex
              px-2.5
              py-1
              bg-blue-50
              text-blue-700
              rounded-full
              text-xs
              font-medium
            "
          >
            {category?.name || '-'}
          </span>
        );
      },
    },

    {
      key: 'duration',
      label: 'Duration',

      render: (val) => (
        <div
          className="
            flex
            items-center
            gap-1.5
            text-sm
            text-gray-600
          "
        >
          <FiClock
            className="text-gray-400"
            size={14}
          />

          {val || '-'}
        </div>
      ),
    },

    {
      key: 'price',
      label: 'Price',

      render: (val) => (
        <span
          className="
            text-sm
            font-semibold
            text-gray-700
          "
        >
          {val || '-'}
        </span>
      ),
    },

    {
      key: 'level',
      label: 'Level',

      render: (val) => (
        <span
          className="
            inline-flex
            px-2
            py-1
            bg-gray-100
            text-gray-600
            rounded-md
            text-xs
          "
        >
          {val || '-'}
        </span>
      ),
    },

    {
      key: 'is_active',
      label: 'Status',

      render: (val) => (
        <span
          className={`
            inline-flex
            items-center
            gap-1.5
            px-2.5
            py-1.5
            rounded-full
            text-[11px]
            font-semibold

            ${
              val
                ? 'bg-green-50 text-green-700'
                : 'bg-red-50 text-red-600'
            }
          `}
        >
          <span
            className={`
              w-1.5
              h-1.5
              rounded-full

              ${
                val
                  ? 'bg-green-500'
                  : 'bg-red-500'
              }
            `}
          />

          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },

    {
      key: 'actions',
      label: 'Actions',

      render: (_, row) => (
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() =>
              handleEditCourse(row)
            }
            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-700
              hover:bg-blue-900
              hover:text-white
              transition
            "
          >
            <FiEdit2 size={14} />
          </button>

          <button
            type="button"
            onClick={() =>
              handleDeleteCourse(row.id)
            }
            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              rounded-lg
              bg-red-50
              text-red-500
              hover:bg-red-500
              hover:text-white
              transition
            "
          >
            <FiTrash2 size={14} />
          </button>
        </div>
      ),
    },
  ];

  // ===================================================
  // CATEGORY COLUMNS
  // ===================================================
  const categoryColumns = [
    {
      key: 'image_url',
      label: 'Image',

      render: (val) => (
        <div
          className="
            w-16
            h-12
            rounded-lg
            overflow-hidden
            bg-gray-100
            border
            border-gray-100
          "
        >
          {val ? (
            <img
              src={val}
              alt="Category"
              className="
                w-full
                h-full
                object-cover
              "
            />
          ) : (
            <div
              className="
                w-full
                h-full
                flex
                items-center
                justify-center
                text-gray-400
              "
            >
              <FiImage />
            </div>
          )}
        </div>
      ),
    },

    {
      key: 'name',
      label: 'Category',

      render: (val, row) => (
        <div>
          <p
            className="
              text-sm
              font-bold
              text-blue-900
            "
          >
            {val || 'Untitled'}
          </p>

          {row.description && (
            <p
              className="
                text-xs
                text-gray-400
                mt-1
                max-w-[250px]
                truncate
              "
            >
              {row.description}
            </p>
          )}
        </div>
      ),
    },

    {
      key: 'slug',
      label: 'Slug',

      render: (val) => (
        <span
          className="
            text-xs
            font-mono
            bg-gray-100
            text-gray-600
            px-2
            py-1
            rounded
          "
        >
          {val || '-'}
        </span>
      ),
    },

    {
      key: 'order',
      label: 'Order',

      render: (val) => (
        <span
          className="
            inline-flex
            items-center
            justify-center
            min-w-[34px]
            h-8
            px-2
            bg-gray-100
            text-gray-700
            rounded-lg
            text-xs
            font-bold
          "
        >
          {val ?? 0}
        </span>
      ),
    },

    {
      key: 'is_active',
      label: 'Status',

      render: (val) => (
        <span
          className={`
            inline-flex
            items-center
            gap-1.5
            px-2.5
            py-1.5
            rounded-full
            text-[11px]
            font-semibold

            ${
              val
                ? 'bg-green-50 text-green-700'
                : 'bg-red-50 text-red-600'
            }
          `}
        >
          <span
            className={`
              w-1.5
              h-1.5
              rounded-full

              ${
                val
                  ? 'bg-green-500'
                  : 'bg-red-500'
              }
            `}
          />

          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },

    {
      key: 'actions',
      label: 'Actions',

      render: (_, row) => (
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() =>
              handleEditCategory(row)
            }
            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-700
              hover:bg-blue-900
              hover:text-white
              transition
            "
          >
            <FiEdit2 size={14} />
          </button>

          <button
            type="button"
            onClick={() =>
              handleDeleteCategory(row.id)
            }
            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              rounded-lg
              bg-red-50
              text-red-500
              hover:bg-red-500
              hover:text-white
              transition
            "
          >
            <FiTrash2 size={14} />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div className="w-full">
      {/* =================================================
          HEADER
      ================================================= */}
      <div
        className="
          flex
          flex-col
          lg:flex-row
          lg:items-center
          lg:justify-between
          gap-4
          mb-6
        "
      >
        <div className="flex items-center gap-3">
          <div
            className="
              w-10
              h-10
              bg-blue-900
              text-white
              rounded-xl
              flex
              items-center
              justify-center
              shadow-sm
            "
          >
            <FiBookOpen size={19} />
          </div>

          <div>
            <h1
              className="
                text-xl
                md:text-2xl
                font-bold
                text-blue-900
              "
            >
              Courses Management
            </h1>

            <p
              className="
                text-xs
                md:text-sm
                text-gray-500
                mt-1
              "
            >
              Manage courses and course categories
            </p>
          </div>
        </div>

        <div
          className="
            flex
            flex-col
            sm:flex-row
            gap-2
          "
        >
          <button
            type="button"
            onClick={handleAddCategory}
            className="
              h-10
              px-4
              inline-flex
              items-center
              justify-center
              gap-2
              bg-white
              border
              border-blue-900
              text-blue-900
              rounded-lg
              text-sm
              font-semibold
              hover:bg-blue-50
              transition
            "
          >
            <FiPlus size={16} />

            Add Category
          </button>

          <button
            type="button"
            onClick={handleAddCourse}
            className="
              h-10
              px-4
              inline-flex
              items-center
              justify-center
              gap-2
              bg-red-500
              text-white
              rounded-lg
              text-sm
              font-semibold
              shadow-sm
              hover:bg-red-600
              transition
            "
          >
            <FiPlus size={16} />

            Add Course
          </button>
        </div>
      </div>

      {/* =================================================
          SUMMARY CARDS
      ================================================= */}
      <div
        className="
          grid
          grid-cols-2
          xl:grid-cols-4
          gap-3
          mb-6
        "
      >
        {/* TOTAL COURSES */}
        <div
          className="
            bg-white
            border
            border-gray-100
            rounded-xl
            p-4
            shadow-sm
          "
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-500">
                Total Courses
              </p>

              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-900
                  mt-1
                "
              >
                {courses.length}
              </p>
            </div>

            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-900
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiBookOpen size={18} />
            </div>
          </div>
        </div>

        {/* ACTIVE */}
        <div
          className="
            bg-white
            border
            border-gray-100
            rounded-xl
            p-4
            shadow-sm
          "
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-500">
                Active Courses
              </p>

              <p
                className="
                  text-2xl
                  font-bold
                  text-green-600
                  mt-1
                "
              >
                {activeCourses}
              </p>
            </div>

            <div
              className="
                w-10
                h-10
                bg-green-50
                text-green-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiCheckCircle size={18} />
            </div>
          </div>
        </div>

        {/* FEATURED */}
        <div
          className="
            bg-white
            border
            border-gray-100
            rounded-xl
            p-4
            shadow-sm
          "
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-500">
                Featured
              </p>

              <p
                className="
                  text-2xl
                  font-bold
                  text-yellow-600
                  mt-1
                "
              >
                {featuredCourses}
              </p>
            </div>

            <div
              className="
                w-10
                h-10
                bg-yellow-50
                text-yellow-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiStar size={18} />
            </div>
          </div>
        </div>

        {/* CATEGORIES */}
        <div
          className="
            bg-white
            border
            border-gray-100
            rounded-xl
            p-4
            shadow-sm
          "
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-500">
                Categories
              </p>

              <p
                className="
                  text-2xl
                  font-bold
                  text-purple-600
                  mt-1
                "
              >
                {activeCategories}
              </p>
            </div>

            <div
              className="
                w-10
                h-10
                bg-purple-50
                text-purple-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiGrid size={18} />
            </div>
          </div>
        </div>
      </div>

      {/* =================================================
          TABLES
      ================================================= */}
      <div className="space-y-6">
        {/* CATEGORY TABLE */}
        <AdminCard
          className="
            border
            border-gray-100
            rounded-xl
            shadow-sm
            overflow-hidden
          "
        >
          <div
            className="
              px-5
              py-4
              border-b
              border-gray-100
              flex
              items-center
              justify-between
            "
          >
            <div>
              <h2
                className="
                  text-sm
                  font-bold
                  text-blue-900
                "
              >
                Course Categories
              </h2>

              <p
                className="
                  text-xs
                  text-gray-400
                  mt-1
                "
              >
                {categories.length} categories found
              </p>
            </div>

            <div
              className="
                w-9
                h-9
                bg-purple-50
                text-purple-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiTag size={16} />
            </div>
          </div>

          <AdminTable
            columns={categoryColumns}
            data={categories}
            loading={loading}
          />
        </AdminCard>

        {/* COURSE TABLE */}
        <AdminCard
          className="
            border
            border-gray-100
            rounded-xl
            shadow-sm
            overflow-hidden
          "
        >
          <div
            className="
              px-5
              py-4
              border-b
              border-gray-100
              flex
              items-center
              justify-between
            "
          >
            <div>
              <h2
                className="
                  text-sm
                  font-bold
                  text-blue-900
                "
              >
                All Courses
              </h2>

              <p
                className="
                  text-xs
                  text-gray-400
                  mt-1
                "
              >
                {courses.length} courses found
              </p>
            </div>

            <div
              className="
                w-9
                h-9
                bg-blue-50
                text-blue-900
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiBookOpen size={16} />
            </div>
          </div>

          <AdminTable
            columns={courseColumns}
            data={courses}
            loading={loading}
          />
        </AdminCard>
      </div>

      {/* =================================================
          COURSE MODAL
      ================================================= */}
      <AdminModal
        isOpen={courseModalOpen}
        onClose={closeCourseModal}
        title={
          editingCourse
            ? 'Edit Course'
            : 'Create Course'
        }
      >
        <form onSubmit={handleCourseSubmit}>
          <div
            className="
              grid
              grid-cols-1
              md:grid-cols-2
              gap-4
            "
          >
            {/* TITLE */}
            <div className="md:col-span-2">
              <label className="admin-label">
                Course Title *
              </label>

              <input
                type="text"
                value={courseFormData.title}
                onChange={(e) => {
                  const title = e.target.value;

                  setCourseFormData({
                    ...courseFormData,
                    title,
                    slug: createSlug(title),
                  });
                }}
                className="admin-input"
                placeholder="Example: Web Development"
                required
              />
            </div>

            {/* SLUG */}
            <div>
              <label className="admin-label">
                Slug *
              </label>

              <input
                type="text"
                value={courseFormData.slug}
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    slug: e.target.value,
                  })
                }
                className="admin-input"
                placeholder="web-development"
                required
              />
            </div>

            {/* CATEGORY */}
            <div>
              <label className="admin-label">
                Category *
              </label>

              <select
                value={courseFormData.category_id}
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    category_id:
                      e.target.value,
                  })
                }
                className="admin-input"
                required
              >
                <option value="">
                  Select Category
                </option>

                {categories.map((category) => (
                  <option
                    key={category.id}
                    value={category.id}
                  >
                    {category.name}
                  </option>
                ))}
              </select>
            </div>

            {/* DURATION */}
            <div>
              <label className="admin-label">
                Duration
              </label>

              <input
                type="text"
                value={courseFormData.duration}
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    duration: e.target.value,
                  })
                }
                className="admin-input"
                placeholder="Example: 3 Months"
              />
            </div>

            {/* LEVEL */}
            <div>
              <label className="admin-label">
                Level
              </label>

              <input
                type="text"
                value={courseFormData.level}
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    level: e.target.value,
                  })
                }
                className="admin-input"
                placeholder="Beginner"
              />
            </div>

            {/* PRICE */}
            <div>
              <label className="admin-label">
                Price
              </label>

              <input
                type="text"
                value={courseFormData.price}
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    price: e.target.value,
                  })
                }
                className="admin-input"
                placeholder="Example: 50"
              />
            </div>

            {/* ORDER */}
            <div>
              <label className="admin-label">
                Display Order
              </label>

              <input
                type="number"
                min="0"
                value={courseFormData.order}
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    order:
                      parseInt(
                        e.target.value,
                        10
                      ) || 0,
                  })
                }
                className="admin-input"
              />
            </div>

            {/* IMAGE */}
            <div className="md:col-span-2">
              <label className="admin-label">
                Course Image
              </label>

              <div
                onClick={() =>
                  courseFileRef.current?.click()
                }
                className="
                  relative
                  border-2
                  border-dashed
                  border-gray-200
                  rounded-xl
                  p-4
                  text-center
                  cursor-pointer
                  bg-gray-50/50
                  hover:border-blue-900
                  hover:bg-blue-50/30
                  transition
                "
              >
                <input
                  ref={courseFileRef}
                  type="file"
                  accept="image/jpeg,image/png,image/webp"
                  onChange={
                    handleCourseImageChange
                  }
                  className="hidden"
                />

                {courseImagePreview ? (
                  <div>
                    <img
                      src={courseImagePreview}
                      alt="Course Preview"
                      className="
                        w-full
                        h-[180px]
                        object-cover
                        rounded-lg
                        mb-3
                      "
                    />

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {courseImageFile
                        ? courseImageFile.name
                        : 'Current Course Image'}
                    </p>

                    <p
                      className="
                        text-xs
                        text-gray-400
                        mt-1
                      "
                    >
                      Click to choose another image
                    </p>
                  </div>
                ) : (
                  <div className="py-5">
                    <div
                      className="
                        w-12
                        h-12
                        bg-blue-50
                        text-blue-900
                        rounded-xl
                        flex
                        items-center
                        justify-center
                        mx-auto
                        mb-3
                      "
                    >
                      <FiImage size={22} />
                    </div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-gray-700
                      "
                    >
                      Click to upload course image
                    </p>

                    <p
                      className="
                        text-xs
                        text-gray-400
                        mt-1
                      "
                    >
                      JPG, PNG or WEBP
                    </p>

                    {editingCourse && (
                      <p
                        className="
                          text-xs
                          text-blue-500
                          mt-2
                        "
                      >
                        Current image will be kept if
                        no new file is selected
                      </p>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* SHORT DESCRIPTION */}
            <div className="md:col-span-2">
              <label className="admin-label">
                Short Description
              </label>

              <textarea
                value={
                  courseFormData.short_description
                }
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    short_description:
                      e.target.value,
                  })
                }
                className="admin-input"
                rows="2"
                placeholder="Short description about the course..."
              />
            </div>

            {/* DESCRIPTION */}
            <div className="md:col-span-2">
              <label className="admin-label">
                Full Description
              </label>

              <textarea
                value={
                  courseFormData.description
                }
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    description:
                      e.target.value,
                  })
                }
                className="admin-input"
                rows="4"
                placeholder="Write full course description..."
              />
            </div>

            {/* STATUS */}
            <div className="md:col-span-2">
              <div
                className="
                  grid
                  grid-cols-1
                  sm:grid-cols-2
                  gap-3
                "
              >
                {/* ACTIVE */}
                <label
                  className={`
                    flex
                    items-center
                    justify-between
                    p-3
                    rounded-xl
                    border
                    cursor-pointer
                    transition

                    ${
                      courseFormData.is_active
                        ? 'bg-green-50 border-green-200'
                        : 'bg-gray-50 border-gray-200'
                    }
                  `}
                >
                  <div className="flex items-center gap-2">
                    {courseFormData.is_active ? (
                      <FiCheckCircle
                        className="text-green-600"
                      />
                    ) : (
                      <FiXCircle
                        className="text-gray-400"
                      />
                    )}

                    <span
                      className="
                        text-sm
                        font-semibold
                        text-gray-700
                      "
                    >
                      Active
                    </span>
                  </div>

                  <input
                    type="checkbox"
                    checked={
                      courseFormData.is_active
                    }
                    onChange={(e) =>
                      setCourseFormData({
                        ...courseFormData,
                        is_active:
                          e.target.checked,
                      })
                    }
                  />
                </label>

                {/* FEATURED */}
                <label
                  className={`
                    flex
                    items-center
                    justify-between
                    p-3
                    rounded-xl
                    border
                    cursor-pointer
                    transition

                    ${
                      courseFormData.is_featured
                        ? 'bg-yellow-50 border-yellow-200'
                        : 'bg-gray-50 border-gray-200'
                    }
                  `}
                >
                  <div className="flex items-center gap-2">
                    <FiStar
                      className={
                        courseFormData.is_featured
                          ? 'text-yellow-600'
                          : 'text-gray-400'
                      }
                    />

                    <span
                      className="
                        text-sm
                        font-semibold
                        text-gray-700
                      "
                    >
                      Featured
                    </span>
                  </div>

                  <input
                    type="checkbox"
                    checked={
                      courseFormData.is_featured
                    }
                    onChange={(e) =>
                      setCourseFormData({
                        ...courseFormData,
                        is_featured:
                          e.target.checked,
                      })
                    }
                  />
                </label>
              </div>
            </div>
          </div>

          {/* FOOTER */}
          <div
            className="
              mt-6
              pt-4
              border-t
              border-gray-100
              flex
              justify-end
              gap-3
            "
          >
            <button
              type="button"
              onClick={closeCourseModal}
              disabled={courseSubmitting}
              className="admin-btn-secondary"
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={courseSubmitting}
              className="
                admin-btn-primary
                disabled:opacity-50
                disabled:cursor-not-allowed
              "
            >
              {courseSubmitting
                ? editingCourse
                  ? 'Updating...'
                  : 'Creating...'
                : editingCourse
                ? 'Update Course'
                : 'Create Course'}
            </button>
          </div>
        </form>
      </AdminModal>

      {/* =================================================
          CATEGORY MODAL
      ================================================= */}
      <AdminModal
        isOpen={categoryModalOpen}
        onClose={closeCategoryModal}
        title={
          editingCategory
            ? 'Edit Category'
            : 'Create Category'
        }
      >
        <form onSubmit={handleCategorySubmit}>
          <div className="space-y-4">
            {/* NAME */}
            <div>
              <label className="admin-label">
                Category Name *
              </label>

              <input
                type="text"
                value={categoryFormData.name}
                onChange={(e) => {
                  const name = e.target.value;

                  setCategoryFormData({
                    ...categoryFormData,
                    name,
                    slug: createSlug(name),
                  });
                }}
                className="admin-input"
                placeholder="Example: IT Courses"
                required
              />
            </div>

            {/* SLUG */}
            <div>
              <label className="admin-label">
                Slug *
              </label>

              <input
                type="text"
                value={categoryFormData.slug}
                onChange={(e) =>
                  setCategoryFormData({
                    ...categoryFormData,
                    slug: e.target.value,
                  })
                }
                className="admin-input"
                placeholder="it-courses"
                required
              />
            </div>

            {/* DESCRIPTION */}
            <div>
              <label className="admin-label">
                Description
              </label>

              <textarea
                value={
                  categoryFormData.description
                }
                onChange={(e) =>
                  setCategoryFormData({
                    ...categoryFormData,
                    description:
                      e.target.value,
                  })
                }
                className="admin-input"
                rows="3"
                placeholder="Category description..."
              />
            </div>

            {/* IMAGE */}
            <div>
              <label className="admin-label">
                Category Image
              </label>

              <div
                onClick={() =>
                  categoryFileRef.current?.click()
                }
                className="
                  border-2
                  border-dashed
                  border-gray-200
                  rounded-xl
                  p-4
                  text-center
                  cursor-pointer
                  bg-gray-50/50
                  hover:border-blue-900
                  hover:bg-blue-50/30
                  transition
                "
              >
                <input
                  ref={categoryFileRef}
                  type="file"
                  accept="image/jpeg,image/png,image/webp"
                  onChange={
                    handleCategoryImageChange
                  }
                  className="hidden"
                />

                {categoryImagePreview ? (
                  <div>
                    <img
                      src={categoryImagePreview}
                      alt="Category Preview"
                      className="
                        w-full
                        h-[170px]
                        object-cover
                        rounded-lg
                        mb-3
                      "
                    />

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {categoryImageFile
                        ? categoryImageFile.name
                        : 'Current Category Image'}
                    </p>

                    <p
                      className="
                        text-xs
                        text-gray-400
                        mt-1
                      "
                    >
                      Click to choose another image
                    </p>
                  </div>
                ) : (
                  <div className="py-5">
                    <div
                      className="
                        w-12
                        h-12
                        bg-blue-50
                        text-blue-900
                        rounded-xl
                        flex
                        items-center
                        justify-center
                        mx-auto
                        mb-3
                      "
                    >
                      <FiImage size={22} />
                    </div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-gray-700
                      "
                    >
                      Click to upload category image
                    </p>

                    <p
                      className="
                        text-xs
                        text-gray-400
                        mt-1
                      "
                    >
                      JPG, PNG or WEBP
                    </p>

                    {editingCategory && (
                      <p
                        className="
                          text-xs
                          text-blue-500
                          mt-2
                        "
                      >
                        Current image will be kept if
                        no new file is selected
                      </p>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* ORDER */}
            <div>
              <label className="admin-label">
                Display Order
              </label>

              <input
                type="number"
                min="0"
                value={categoryFormData.order}
                onChange={(e) =>
                  setCategoryFormData({
                    ...categoryFormData,
                    order:
                      parseInt(
                        e.target.value,
                        10
                      ) || 0,
                  })
                }
                className="admin-input"
              />

              <p
                className="
                  text-[10px]
                  text-gray-400
                  mt-1
                "
              >
                Lower number appears first
              </p>
            </div>

            {/* ACTIVE */}
            <label
              className={`
                flex
                items-center
                justify-between
                p-4
                border
                rounded-xl
                cursor-pointer

                ${
                  categoryFormData.is_active
                    ? 'bg-green-50 border-green-200'
                    : 'bg-gray-50 border-gray-200'
                }
              `}
            >
              <div className="flex items-center gap-3">
                <div
                  className={`
                    w-9
                    h-9
                    rounded-lg
                    flex
                    items-center
                    justify-center

                    ${
                      categoryFormData.is_active
                        ? 'bg-green-100 text-green-600'
                        : 'bg-gray-200 text-gray-500'
                    }
                  `}
                >
                  {categoryFormData.is_active ? (
                    <FiCheckCircle />
                  ) : (
                    <FiXCircle />
                  )}
                </div>

                <div>
                  <p
                    className="
                      text-sm
                      font-semibold
                      text-gray-700
                    "
                  >
                    Active Category
                  </p>

                  <p
                    className="
                      text-xs
                      text-gray-400
                    "
                  >
                    Show this category on the website
                  </p>
                </div>
              </div>

              <input
                type="checkbox"
                checked={
                  categoryFormData.is_active
                }
                onChange={(e) =>
                  setCategoryFormData({
                    ...categoryFormData,
                    is_active:
                      e.target.checked,
                  })
                }
              />
            </label>
          </div>

          {/* FOOTER */}
          <div
            className="
              mt-6
              pt-4
              border-t
              border-gray-100
              flex
              justify-end
              gap-3
            "
          >
            <button
              type="button"
              onClick={closeCategoryModal}
              disabled={categorySubmitting}
              className="admin-btn-secondary"
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={categorySubmitting}
              className="
                admin-btn-primary
                disabled:opacity-50
                disabled:cursor-not-allowed
              "
            >
              {categorySubmitting
                ? editingCategory
                  ? 'Updating...'
                  : 'Creating...'
                : editingCategory
                ? 'Update Category'
                : 'Create Category'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminCourses;
